CREATE TABLE IF NOT EXISTS gis_final_identity_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_feature_id uuid NOT NULL REFERENCES gis_spatial_features(id) ON DELETE CASCADE, target_feature_id uuid REFERENCES gis_spatial_features(id) ON DELETE SET NULL, decision text NOT NULL, confidence text NOT NULL, method text NOT NULL, rationale text NOT NULL, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, reviewer_id text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_feature_id));
CREATE INDEX IF NOT EXISTS idx_gis_final_identity_decisions ON gis_final_identity_decisions(decision,confidence);